CREATE TABLE IF NOT EXISTS p11_grab_policies (id BIGINT PRIMARY KEY,enabled BOOLEAN NOT NULL,time_reward_enabled BOOLEAN NOT NULL,max_times INT NOT NULL,buy_max INT NOT NULL,buy_price INT NOT NULL,energy INT NOT NULL,max_millis BIGINT NOT NULL,rewards_json TEXT NOT NULL,rewards_hash VARCHAR(64) NOT NULL,source TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
